import{_ as p,a0 as i,w as c,s as l,I as t,x as e,a1 as a,A as o,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"计算机实验室之树莓派：课程 10 输入01 | LCTT x X-CMD","titleTemplate":false,"description":"计算机实验室之树莓派：课程 10 输入01 | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"计算机实验室之树莓派：课程 10 输入01 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"计算机实验室之树莓派：课程 10 输入01 | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20150616 Computer Laboratory - Raspberry Pi- Lesson 10 Input01","title":"计算机实验室之树莓派：课程 10 输入01","tag":"201904","desc":""},"relativePath":"201904/20150616 Computer Laboratory - Raspberry Pi- Lesson 10 Input01.md","filePath":"[post].md"}'),r={name:"201904/20150616 Computer Laboratory - Raspberry Pi- Lesson 10 Input01.md"};function h(b,d,k,g,u,y){const s=i("Link");return c(),l("div",null,[d[29]||(d[29]=t("h1",{id:"计算机实验室之树莓派-课程-10-输入01",tabindex:"-1"},[e("计算机实验室之树莓派：课程 10 输入01 "),t("a",{class:"header-anchor",href:"#计算机实验室之树莓派-课程-10-输入01","aria-label":"Permalink to “计算机实验室之树莓派：课程 10 输入01”"},"​")],-1)),d[30]||(d[30]=t("p",null,"欢迎进入输入课程系列。在本系列，你将会学会如何使用键盘接收输入给树莓派。我们将会从揭示输入开始本课，然后转向更传统的文本提示符。",-1)),d[31]||(d[31]=t("p",null,"这是第一堂输入课，会教授一些关于驱动和链接的理论，同样也包含键盘的知识，最后以在屏幕上显示文本结束。",-1)),d[32]||(d[32]=t("h3",{id:"_1、开始",tabindex:"-1"},[e("1、开始 "),t("a",{class:"header-anchor",href:"#_1、开始","aria-label":"Permalink to “1、开始”"},"​")],-1)),t("p",null,[d[1]||(d[1]=e("希望你已经完成了 OK 系列课程，这会对你完成屏幕系列课程很有帮助。很多 OK 课程上的文件会被使用而不会做解释。如果你没有这些文件，或者希望使用一个正确的实现，可以从该堂课的",-1)),a(s,{href:"https://www.cl.cam.ac.uk/projects/raspberrypi/tutorials/os/downloads.html"},{default:o(()=>[...d[0]||(d[0]=[e("下载页",-1)])]),_:1}),d[2]||(d[2]=e("下载模板。如果你使用你自己的实现，请删除调用了 ",-1)),d[3]||(d[3]=t("code",null,"SetGraphicsAddress",-1)),d[4]||(d[4]=e(" 之后全部的代码。",-1))]),d[33]||(d[33]=n('<h3 id="_2、usb" tabindex="-1">2、USB <a class="header-anchor" href="#_2、usb" aria-label="Permalink to “2、USB”">​</a></h3><p>如你所知，树莓派 B 型有两个 USB 接口，通常用来连接一个鼠标和一个键盘。这是一个非常好的设计决策，USB 是一个非常通用的接口，很多种设备都可以使用它。这就很容易为它设计新外设，很容易为它编写设备驱动，而且通过 USB 集线器可以非常容易扩展。还能更好吗？当然是不能，实际上对一个操作系统开发者来说，这就是我们的噩梦。USB 标准太大了。我是说真的，在你思考如何连接设备之前，它的文档将近 700 页。</p><blockquote><p>USB 标准的设计目的是通过复杂的软件来简化硬件交互。</p></blockquote><p>我和很多爱好操作系统的开发者谈过这些，而他们全部都说几句话：不要抱怨。“实现这个需要花费很久时间”，“你不可能写出关于 USB 的教程”，“收益太小了”。在很多方面，他们是对的，我不可能写出一个关于 USB 标准的教程，那得花费几周时间。我同样不能教授如何为全部所有的设备编写外设驱动，所以使用自己写的驱动是没什么用的。然而，即便不能做到最好，我仍然可以获取一个正常工作的 USB 驱动，拿一个键盘驱动，然后教授如何在操作系统中使用它们。我开始寻找可以运行在一个甚至不知道文件是什么的操作系统的自由驱动，但是我一个都找不到，它们都太高层了，所以我尝试写一个。大家说的都对，这耗费了我几周时间。然而我可以高兴的说我做的这些工作没有获取操作系统以外的帮助，并且可以和鼠标和键盘通信。这绝不是完整的、高效的，或者正确的，但是它能工作。驱动是以 C 编写的，而且有兴趣的可以在下载页找到全部源代码。</p><p>所以，这一个教程不会是 USB 标准的课程（一点也没有）。实际上我们将会看到如何使用其他人的代码。</p><h3 id="_3、链接" tabindex="-1">3、链接 <a class="header-anchor" href="#_3、链接" aria-label="Permalink to “3、链接”">​</a></h3><p>既然我们要引进外部代码到操作系统，我们就需要谈一谈<ruby>链接<rt>linking</rt></ruby>。链接是一种过程，可以在程序或者操作系统中链接函数。这意味着当一个程序生成之后，我们不必要编写每一个函数（几乎可以肯定，实际上并非如此）。链接就是我们做的用来把我们程序和别人代码中的函数连结在一起。这个实际上已经在我们的操作系统进行了，因为链接器把所有不同的文件链接在一起，每个都是分开编译的。</p><blockquote><p>链接允许我们制作可重用的代码库，所有人都可以在他们的程序中使用。</p></blockquote><p>有两种链接方式：静态和动态。静态链接就像我们在制作自己的操作系统时进行的。链接器找到全部函数的地址，然后在链接结束前，将这些地址都写入代码中。动态链接是在程序“完成”之后。当程序加载后，动态链接器检查程序，然后在操作系统的库找到所有不在程序里的函数。这就是我们的操作系统最终应该能够完成的一项工作，但是现在所有东西都将是静态链接的。</p><blockquote><p>程序经常调用调用库，这些库会调用其它的库，直到最终调用了我们写的操作系统的库。</p></blockquote>',10)),t("p",null,[d[6]||(d[6]=e("我编写的 USB 驱动程序适合静态编译。这意味着我给你的是每个文件的编译后的代码，然后链接器找到你的代码中的那些没有实现的函数，就将这些函数链接到我的代码。在本课的 ",-1)),a(s,{href:"https://www.cl.cam.ac.uk/projects/raspberrypi/tutorials/os/downloads.html"},{default:o(()=>[...d[5]||(d[5]=[e("下载页",-1)])]),_:1}),d[7]||(d[7]=e(" 是一个 makefile 和我的 USB 驱动，这是接下来需要的。下载并使用这个 makefile 替换你的代码中的 makefile， 同事将驱动放在和这个 makefile 相同的文件夹。",-1))]),d[34]||(d[34]=n('<h3 id="_4、键盘" tabindex="-1">4、键盘 <a class="header-anchor" href="#_4、键盘" aria-label="Permalink to “4、键盘”">​</a></h3><p>为了将输入传给我们的操作系统，我们需要在某种程度上理解键盘是如何实际工作的。键盘有两种按键：普通键和修饰键。普通按键是字母、数字、功能键，等等。它们构成了键盘上几乎全部按键。修饰键是多达 8 个的特殊键。它们是左 shift、右 shift、左 ctrl、右 ctrl、左 alt、右 alt、左 GUI 和右 GUI。键盘可以检测出所有的组合中那个修饰键被按下了，以及最多 6 个普通键。每次一个按钮变化了（例如，是按下了还是释放了），键盘就会报告给电脑。通常，键盘也会有 3 个 LED 灯，分别指示大写锁定，数字键锁定，和滚动锁定，这些都是由电脑控制的，而不是键盘自己。键盘也可能有更多的灯，比如电源、静音，等等。</p><p>对于标准 USB 键盘，有一个按键值的表，每个键盘按键都一个唯一的数字，每个可能的 LED 也类似。下面的表格列出了前 126 个值。</p><p>表 4.1 USB 键盘值</p><div class="table-wrap"><table><thead><tr><th>序号</th><th>描述</th><th>序号</th><th>描述</th><th>序号</th><th>描述</th><th>序号</th><th>描述</th></tr></thead><tbody><tr><td>4</td><td><code>a</code> 和 <code>A</code></td><td>5</td><td><code>b</code> 和 <code>B</code></td><td>6</td><td><code>c</code> 和 <code>C</code></td><td>7</td><td><code>d</code> 和 <code>D</code></td></tr><tr><td>8</td><td><code>e</code> 和 <code>E</code></td><td>9</td><td><code>f</code> 和 <code>F</code></td><td>10</td><td><code>g</code> 和 <code>G</code></td><td>11</td><td><code>h</code> 和 <code>H</code></td></tr><tr><td>12</td><td><code>i</code> 和 <code>I</code></td><td>13</td><td><code>j</code> 和 <code>J</code></td><td>14</td><td><code>k</code> 和 <code>K</code></td><td>15</td><td><code>l</code> 和 <code>L</code></td></tr><tr><td>16</td><td><code>m</code> 和 <code>M</code></td><td>17</td><td><code>n</code> 和 <code>N</code></td><td>18</td><td><code>o</code> 和 <code>O</code></td><td>19</td><td><code>p</code> 和 <code>P</code></td></tr><tr><td>20</td><td><code>q</code> 和 <code>Q</code></td><td>21</td><td><code>r</code> 和 <code>R</code></td><td>22</td><td><code>s</code> 和 <code>S</code></td><td>23</td><td><code>t</code> 和 <code>T</code></td></tr><tr><td>24</td><td><code>u</code> 和 <code>U</code></td><td>25</td><td><code>v</code> 和 <code>V</code></td><td>26</td><td><code>w</code> 和 <code>W</code></td><td>27</td><td><code>x</code> 和 <code>X</code></td></tr><tr><td>28</td><td><code>y</code> 和 <code>Y</code></td><td>29</td><td><code>z</code> 和 <code>Z</code></td><td>30</td><td><code>1</code> 和 <code>!</code></td><td>31</td><td><code>2</code> 和 <code>@</code></td></tr><tr><td>32</td><td><code>3</code> 和 <code>#</code></td><td>33</td><td><code>4</code> 和 <code>$</code></td><td>34</td><td><code>5</code> 和 <code>%</code></td><td>35</td><td><code>6</code> 和 <code>^</code></td></tr><tr><td>36</td><td><code>7</code> 和 <code>&amp;</code></td><td>37</td><td><code>8</code> 和 <code>*</code></td><td>38</td><td><code>9</code> 和 <code>(</code></td><td>39</td><td><code>0</code> 和 <code>)</code></td></tr><tr><td>40</td><td><code>Return</code>（<code>Enter</code>）</td><td>41</td><td><code>Escape</code></td><td>42</td><td><code>Delete</code>（<code>Backspace</code>）</td><td>43</td><td><code>Tab</code></td></tr><tr><td>44</td><td><code>Spacebar</code></td><td>45</td><td><code>-</code> 和 <code>_</code></td><td>46</td><td><code>=</code> 和 <code>+</code></td><td>47</td><td><code>[</code> 和 <code>{</code></td></tr><tr><td>48</td><td><code>]</code> 和 <code>}</code></td><td>49</td><td><code>\\</code> 和 `</td><td>`</td><td>50</td><td><code>#</code> 和 <code>~</code></td><td>51</td></tr><tr><td>52</td><td><code>&#39;</code> 和 <code>&quot;</code></td><td>53</td><td>` 和 <code>~</code></td><td>54</td><td><code>,</code> 和 <code>&lt;</code></td><td>55</td><td><code>.</code> 和 <code>&gt;</code></td></tr><tr><td>56</td><td><code>/</code> 和 <code>?</code></td><td>57</td><td><code>Caps Lock</code></td><td>58</td><td><code>F1</code></td><td>59</td><td><code>F2</code></td></tr><tr><td>60</td><td><code>F3</code></td><td>61</td><td><code>F4</code></td><td>62</td><td><code>F5</code></td><td>63</td><td><code>F6</code></td></tr><tr><td>64</td><td><code>F7</code></td><td>65</td><td><code>F8</code></td><td>66</td><td><code>F9</code></td><td>67</td><td><code>F10</code></td></tr><tr><td>68</td><td><code>F11</code></td><td>69</td><td><code>F12</code></td><td>70</td><td><code>Print Screen</code></td><td>71</td><td><code>Scroll Lock</code></td></tr><tr><td>72</td><td><code>Pause</code></td><td>73</td><td><code>Insert</code></td><td>74</td><td><code>Home</code></td><td>75</td><td><code>Page Up</code></td></tr><tr><td>76</td><td><code>Delete forward</code></td><td>77</td><td><code>End</code></td><td>78</td><td><code>Page Down</code></td><td>79</td><td><code>Right Arrow</code></td></tr><tr><td>80</td><td><code>Left Arrow</code></td><td>81</td><td><code>Down Arrow</code></td><td>82</td><td><code>Up Arrow</code></td><td>83</td><td><code>Num Lock</code></td></tr><tr><td>84</td><td>小键盘 <code>/</code></td><td>85</td><td>小键盘 <code>*</code></td><td>86</td><td>小键盘 <code>-</code></td><td>87</td><td>小键盘 <code>+</code></td></tr><tr><td>88</td><td>小键盘 <code>Enter</code></td><td>89</td><td>小键盘 <code>1</code> 和 <code>End</code></td><td>90</td><td>小键盘 <code>2</code> 和 <code>Down Arrow</code></td><td>91</td><td>小键盘 <code>3</code> 和 <code>Page Down</code></td></tr><tr><td>92</td><td>小键盘 <code>4</code> 和 <code>Left Arrow</code></td><td>93</td><td>小键盘 <code>5</code></td><td>94</td><td>小键盘 <code>6</code> 和 <code>Right Arrow</code></td><td>95</td><td>小键盘 <code>7</code> 和 <code>Home</code></td></tr><tr><td>96</td><td>小键盘 <code>8</code> 和 <code>Up Arrow</code></td><td>97</td><td>小键盘 <code>9</code> 和 <code>Page Up</code></td><td>98</td><td>小键盘 <code>0</code> 和 <code>Insert</code></td><td>99</td><td>小键盘 <code>.</code> 和 <code>Delete</code></td></tr><tr><td>100</td><td><code>\\</code> 和 `</td><td>`</td><td>101</td><td><code>Application</code></td><td>102</td><td><code>Power</code></td><td>103</td></tr><tr><td>104</td><td><code>F13</code></td><td>105</td><td><code>F14</code></td><td>106</td><td><code>F15</code></td><td>107</td><td><code>F16</code></td></tr><tr><td>108</td><td><code>F17</code></td><td>109</td><td><code>F18</code></td><td>110</td><td><code>F19</code></td><td>111</td><td><code>F20</code></td></tr><tr><td>112</td><td><code>F21</code></td><td>113</td><td><code>F22</code></td><td>114</td><td><code>F23</code></td><td>115</td><td><code>F24</code></td></tr><tr><td>116</td><td><code>Execute</code></td><td>117</td><td><code>Help</code></td><td>118</td><td><code>Menu</code></td><td>119</td><td><code>Select</code></td></tr><tr><td>120</td><td><code>Stop</code></td><td>121</td><td><code>Again</code></td><td>122</td><td><code>Undo</code></td><td>123</td><td><code>Cut</code></td></tr><tr><td>124</td><td><code>Copy</code></td><td>125</td><td><code>Paste</code></td><td>126</td><td><code>Find</code></td><td>127</td><td><code>Mute</code></td></tr><tr><td>128</td><td><code>Volume Up</code></td><td>129</td><td><code>Volume Down</code></td><td></td><td></td><td></td><td></td></tr></tbody></table></div>',5)),t("p",null,[d[9]||(d[9]=e("完全列表可以在",-1)),a(s,{href:"https://www.cl.cam.ac.uk/projects/raspberrypi/tutorials/os/downloads/hut1_12v2.pdf"},{default:o(()=>[...d[8]||(d[8]=[e("HID 页表 1.12",-1)])]),_:1}),d[10]||(d[10]=e("的 53 页，第 10 节找到。",-1))]),d[35]||(d[35]=n(`<h3 id="_5、车轮后的螺母" tabindex="-1">5、车轮后的螺母 <a class="header-anchor" href="#_5、车轮后的螺母" aria-label="Permalink to “5、车轮后的螺母”">​</a></h3><p>通常，当你使用其他人的代码，他们会提供一份自己代码的总结，描述代码都做了什么，粗略介绍了是如何工作的，以及什么情况下会出错。下面是一个使用我的 USB 驱动的相关步骤要求。</p><blockquote><p>这些总结和代码的描述组成了一个 API - 应用程序产品接口。</p></blockquote><p>表 5.1 CSUD 中和键盘相关的函数</p><div class="table-wrap"><table><thead><tr><th>函数</th><th>参数</th><th>返回值</th><th>描述</th></tr></thead><tbody><tr><td><code>UsbInitialise</code></td><td>无</td><td><code>r0</code> 是结果码</td><td>这个方法是一个集多种功能于一身的方法，它加载 USB 驱动程序，枚举所有设备并尝试与它们通信。这种方法通常需要大约一秒钟的时间来执行，但是如果插入几个 USB 集线器，执行时间会明显更长。在此方法完成之后，键盘驱动程序中的方法就可用了，不管是否确实插入了键盘。返回代码如下解释。</td></tr><tr><td><code>UsbCheckForChange</code></td><td>无</td><td>无</td><td>本质上提供与 <code>UsbInitialise</code> 相同的效果，但不提供相同的一次初始化。该方法递归地检查每个连接的集线器上的每个端口，如果已经添加了新设备，则添加它们。如果没有更改，这应该是非常快的，但是如果连接了多个设备的集线器，则可能需要几秒钟的时间。</td></tr><tr><td><code>KeyboardCount</code></td><td>无</td><td><code>r0</code> 是计数</td><td>返回当前连接并检测到的键盘数量。<code>UsbCheckForChange</code> 可能会对此进行更新。默认情况下最多支持 4 个键盘。可以通过这个驱动程序访问多达这么多的键盘。</td></tr><tr><td><code>KeyboardGetAddress</code></td><td><code>r0</code> 是索引</td><td><code>r0</code> 是地址</td><td>检索给定键盘的地址。所有其他函数都需要一个键盘地址，以便知道要访问哪个键盘。因此，要与键盘通信，首先要检查计数，然后检索地址，然后使用其他方法。注意，在调用 <code>UsbCheckForChange</code> 之后，此方法返回的键盘顺序可能会改变。</td></tr><tr><td><code>KeyboardPoll</code></td><td><code>r0</code> 是地址</td><td><code>r0</code> 是结果码</td><td>从键盘读取当前键状态。这是通过直接轮询设备来操作的，与最佳实践相反。这意味着，如果没有频繁地调用此方法，可能会错过一个按键。所有读取方法只返回上次轮询时的值。</td></tr><tr><td><code>KeyboardGetModifiers</code></td><td><code>r0</code> 是地址</td><td><code>r0</code> 是修饰键状态</td><td>检索上次轮询时修饰键的状态。这是两边的 <code>shift</code> 键、<code>alt</code> 键和 <code>GUI</code> 键。这回作为一个位字段返回，这样，位 0 中的 1 表示左控件被保留，位 1 表示左 <code>shift</code>，位 2 表示左 <code>alt</code> ，位 3 表示左 <code>GUI</code>，位 4 到 7 表示前面几个键的右版本。如果有问题，<code>r0</code> 包含 0。</td></tr><tr><td><code>KeyboardGetKeyDownCount</code></td><td><code>r0</code> 是地址</td><td><code>r0</code> 是计数</td><td>检索当前按下键盘的键数。这排除了修饰键。这通常不能超过 6。如果有错误，这个方法返回 0。</td></tr><tr><td><code>KeyboardGetKeyDown</code></td><td><code>r0</code> 是地址，<code>r1</code> 键号</td><td><code>r0</code> 是扫描码</td><td>检索特定按下键的扫描码（见表 4.1）。通常，要计算出哪些键是按下的，可以调用 <code>KeyboardGetKeyDownCount</code>，然后多次调用 <code>KeyboardGetKeyDown</code> ，将 <code>r1</code> 的值递增，以确定哪些键是按下的。如果有问题，返回 0。可以（但不建议这样做）在不调用 <code>KeyboardGetKeyDownCount</code> 的情况下调用此方法将 0 解释为没有按下的键。注意，顺序或扫描代码可以随机更改（有些键盘按数字排序，有些键盘按时间排序，没有任何保证）。</td></tr><tr><td><code>KeyboardGetKeyIsDown</code></td><td><code>r0</code> 是地址，<code>r1</code> 扫描码</td><td><code>r0</code> 是状态</td><td>除了 <code>KeyboardGetKeyDown</code> 之外，还可以检查按下的键中是否有特定的扫描码。如果没有，返回 0；如果有，返回一个非零值。当检测特定的扫描码（例如寻找 <code>ctrl+c</code>）时更快。出错时，返回 0。</td></tr><tr><td><code>KeyboardGetLedSupport</code></td><td><code>r0</code> 是地址</td><td><code>r0</code> 是 LED</td><td>检查特定键盘支持哪些 LED。第 0 位代表数字锁定，第 1 位代表大写锁定，第 2 位代表滚动锁定，第 3 位代表合成，第 4 位代表假名，第 5 位代表电源，第 6 位代表 Shift ，第 7 位代表静音。根据 USB 标准，这些 LED 都不是自动更新的（例如，当检测到大写锁定扫描代码时，必须手动设置大写锁定 LED）。</td></tr><tr><td><code>KeyboardSetLeds</code></td><td><code>r0</code> 是地址， <code>r1</code> 是 LED</td><td><code>r0</code> 是结果码</td><td>试图打开/关闭键盘上指定的 LED 灯。查看下面的结果代码值。参见 <code>KeyboardGetLedSupport</code> 获取 LED 的值。</td></tr></tbody></table></div><p>有几种方法返回“返回值”。这些都是 C 代码的老生常谈了，就是用数字代表函数调用发生了什么。通常情况， 0 总是代表操作成功。下面的是驱动用到的返回值。</p><blockquote><p>返回值是一种处理错误的简单方法，但是通常更优雅的解决途径会出现于更高层次的代码。</p></blockquote><p>表 5.2 - CSUD 返回值</p><div class="table-wrap"><table><thead><tr><th>代码</th><th>描述</th></tr></thead><tbody><tr><td>0</td><td>方法成功完成。</td></tr><tr><td>-2</td><td>参数：函数调用了无效参数。</td></tr><tr><td>-4</td><td>设备：设备没有正确响应请求。</td></tr><tr><td>-5</td><td>不匹配：驱动不适用于这个请求或者设备。</td></tr><tr><td>-6</td><td>编译器：驱动没有正确编译，或者被破坏了。</td></tr><tr><td>-7</td><td>内存：驱动用尽了内存。</td></tr><tr><td>-8</td><td>超时：设备没有在预期的时间内响应请求。</td></tr><tr><td>-9</td><td>断开连接：被请求的设备断开连接，或者不能使用。</td></tr></tbody></table></div><p>驱动的通常用法如下：</p><ol><li>调用 <code>UsbInitialise</code></li><li>调用 <code>UsbCheckForChange</code></li><li>调用 <code>KeyboardCount</code></li><li>如果返回 0，重复步骤 2。</li><li>针对你支持的每个键盘： 1. 调用 <code>KeyboardGetAddress</code> 2. 调用 <code>KeybordGetKeyDownCount</code> 3. 针对每个按下的按键： <ol><li>检查它是否已经被按下了</li><li>保存按下的按键</li></ol></li></ol><pre><code>4. 针对每个保存的按键：
  3. 检查按键是否被释放了
  4. 如果释放了就删除
</code></pre><ol start="6"><li>根据按下/释放的案件执行操作</li><li>重复步骤 2</li></ol><p>最后，你可以对键盘做所有你想做的任何事了，而这些方法应该允许你访问键盘的全部功能。在接下来的两节课，我们将会着眼于完成文本终端的输入部分，类似于大部分的命令行电脑，以及命令的解释。为了做这些，我们将需要在更有用的形式下得到一个键盘输入。你可能注意到我的驱动是（故意的）没有太大帮助，因为它并没有方法来判断是否一个按键刚刚按下或释放了，它只有方法来判断当前那个按键是按下的。这就意味着我们需要自己编写这些方法。</p><h3 id="_6、可用更新" tabindex="-1">6、可用更新 <a class="header-anchor" href="#_6、可用更新" aria-label="Permalink to “6、可用更新”">​</a></h3><p>首先，让我们实现一个 <code>KeyboardUpdate</code> 方法，检查第一个键盘，并使用轮询方法来获取当前的输入，以及保存最后一个输入来对比。然后我们可以使用这个数据和其它方法来将扫描码转换成按键。这个方法应该按照下面的说明准确操作：</p><blockquote><p>重复检查更新被称为“轮询”。这是针对驱动 IO 中断而言的，这种情况下设备在准备好后会发一个信号。</p></blockquote><ol><li>提取一个保存好的键盘地址（初始值为 0）。</li><li>如果不是 0 ，进入步骤 9.</li><li>调用 <code>UsbCheckForChange</code> 检测新键盘。</li><li>调用 <code>KeyboardCount</code> 检测有几个键盘在线。</li><li>如果返回 0，意味着没有键盘可以让我们操作，只能退出了。</li><li>调用 <code>KeyboardGetAddress</code> 参数是 0，获取第一个键盘的地址。</li><li>保存这个地址。</li><li>如果这个值是 0，那么退出，这里应该有些问题。</li><li>调用 <code>KeyboardGetKeyDown</code> 6 次，获取每次按键按下的值并保存。</li><li>调用 <code>KeyboardPoll</code></li><li>如果返回值非 0，进入步骤 3。这里应该有些问题（比如键盘断开连接）。</li></ol><p>要保存上面提到的值，我们将需要下面 <code>.data</code> 段的值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.section .data</span></span>
<span class="line"><span>.align 2</span></span>
<span class="line"><span>KeyboardAddress:</span></span>
<span class="line"><span>.int 0</span></span>
<span class="line"><span>KeyboardOldDown:</span></span>
<span class="line"><span>.rept 6</span></span>
<span class="line"><span>.hword 0</span></span>
<span class="line"><span>.endr</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.hword num 直接将半字的常数插入文件。</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.rept num [commands] .endr 复制 \`commands\` 命令到输出 num 次。</span></span></code></pre></div><p>试着自己实现这个方法。对此，我的实现如下：</p><p>1、我们加载键盘的地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.section .text</span></span>
<span class="line"><span>.globl KeyboardUpdate</span></span>
<span class="line"><span>KeyboardUpdate:</span></span>
<span class="line"><span>push {r4,r5,lr}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>kbd .req r4</span></span>
<span class="line"><span>ldr r0,=KeyboardAddress</span></span>
<span class="line"><span>ldr kbd,[r0]</span></span></code></pre></div><p>2、如果地址非 0，就说明我们有一个键盘。调用 <code>UsbCheckForChanges</code> 慢，所以如果一切正常，我们要避免调用这个函数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>teq kbd,#0</span></span>
<span class="line"><span>bne haveKeyboard$</span></span></code></pre></div><p>3、如果我们一个键盘都没有，我们就必须检查新设备。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>getKeyboard$:</span></span>
<span class="line"><span>bl UsbCheckForChange</span></span></code></pre></div><p>4、如果有新键盘添加，我们就会看到这个。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bl KeyboardCount</span></span></code></pre></div><p>5、如果没有键盘，我们就没有键盘地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>teq r0,#0</span></span>
<span class="line"><span>ldreq r1,=KeyboardAddress</span></span>
<span class="line"><span>streq r0,[r1]</span></span>
<span class="line"><span>beq return$</span></span></code></pre></div><p>6、让我们获取第一个键盘的地址。你可能想要支持更多键盘。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mov r0,#0</span></span>
<span class="line"><span>bl KeyboardGetAddress</span></span></code></pre></div><p>7、保存键盘地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ldr r1,=KeyboardAddress</span></span>
<span class="line"><span>str r0,[r1]</span></span></code></pre></div><p>8、如果我们没有键盘地址，这里就没有其它活要做了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>teq r0,#0</span></span>
<span class="line"><span>beq return$</span></span>
<span class="line"><span>mov kbd,r0</span></span></code></pre></div><p>9、循环查询全部按键，在 <code>KeyboardOldDown</code> 保存下来。如果我们询问的太多了，返回 0 也是正确的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>saveKeys$:</span></span>
<span class="line"><span>  mov r0,kbd</span></span>
<span class="line"><span>  mov r1,r5</span></span>
<span class="line"><span>  bl KeyboardGetKeyDown</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  ldr r1,=KeyboardOldDown</span></span>
<span class="line"><span>  add r1,r5,lsl #1</span></span>
<span class="line"><span>  strh r0,[r1]</span></span>
<span class="line"><span>  add r5,#1</span></span>
<span class="line"><span>  cmp r5,#6</span></span>
<span class="line"><span>  blt saveKeys$</span></span></code></pre></div><p>10、现在我们得到了新的按键。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mov r0,kbd</span></span>
<span class="line"><span>bl KeyboardPoll</span></span></code></pre></div><p>11、最后我们要检查 <code>KeyboardOldDown</code> 是否工作了。如果没工作，那么我们可能是断开连接了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>teq r0,#0</span></span>
<span class="line"><span>bne getKeyboard$</span></span>
<span class="line"><span></span></span>
<span class="line"><span>return$:</span></span>
<span class="line"><span>pop {r4,r5,pc}</span></span>
<span class="line"><span>.unreq kbd</span></span></code></pre></div><p>有了我们新的 <code>KeyboardUpdate</code> 方法，检查输入变得简单，固定周期调用这个方法就行，而它甚至可以检查键盘是否断开连接，等等。这是一个有用的方法，因为我们实际的按键处理会根据条件不同而有所差别，所以能够用一个函数调以它的原始方式获取当前的输入是可行的。下一个方法我们希望它是 <code>KeyboardGetChar</code>，简单的返回下一个按下的按钮的 ASCII 字符，或者如果没有按键按下就返回 0。这可以扩展到支持如果它按下一个特定时间当做多次按下按键，也支持锁定键和修饰键。</p><p>如果我们有一个 <code>KeyWasDown</code> 方法可以使这个方法有用起来，如果给定的扫描代码不在 <code>KeyboardOldDown</code> 值中，它只返回 0，否则返回一个非零值。你可以自己尝试一下。与往常一样，可以在下载页面找到解决方案。</p><h3 id="_7、查找表" tabindex="-1">7、查找表 <a class="header-anchor" href="#_7、查找表" aria-label="Permalink to “7、查找表”">​</a></h3><p><code>KeyboardGetChar</code> 方法如果写得不好，可能会非常复杂。有 100 多种扫描码，每种代码都有不同的效果，这取决于 shift 键或其他修饰符的存在与否。并不是所有的键都可以转换成一个字符。对于一些字符，多个键可以生成相同的字符。在有如此多可能性的情况下，一个有用的技巧是查找表。查找表与物理意义上的查找表非常相似，它是一个值及其结果的表。对于一些有限的函数，推导出答案的最简单方法就是预先计算每个答案，然后通过检索返回正确的答案。在这种情况下,我们可以在内存中建立一个序列的值，序列中第 n 个值就是扫描代码 n 的 ASCII 字符代码。这意味着如果一个键被按下，我们的方法只需要检测到，然后从表中检索它的值。此外，我们可以为当按住 shift 键时的值单独创建一个表，这样按下 shift 键就可以简单地换个我们用的表。</p><blockquote><p>在编程的许多领域，程序越大，速度越快。查找表很大，但是速度很快。有些问题可以通过查找表和普通函数的组合来解决。</p></blockquote><p>在 <code>.section .data</code> 命令之后，复制下面的表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.align 3</span></span>
<span class="line"><span>KeysNormal:</span></span>
<span class="line"><span>    .byte 0x0, 0x0, 0x0, 0x0, &#39;a&#39;, &#39;b&#39;, &#39;c&#39;, &#39;d&#39;</span></span>
<span class="line"><span>    .byte &#39;e&#39;, &#39;f&#39;, &#39;g&#39;, &#39;h&#39;, &#39;i&#39;, &#39;j&#39;, &#39;k&#39;, &#39;l&#39;</span></span>
<span class="line"><span>    .byte &#39;m&#39;, &#39;n&#39;, &#39;o&#39;, &#39;p&#39;, &#39;q&#39;, &#39;r&#39;, &#39;s&#39;, &#39;t&#39;</span></span>
<span class="line"><span>    .byte &#39;u&#39;, &#39;v&#39;, &#39;w&#39;, &#39;x&#39;, &#39;y&#39;, &#39;z&#39;, &#39;1&#39;, &#39;2&#39;</span></span>
<span class="line"><span>    .byte &#39;3&#39;, &#39;4&#39;, &#39;5&#39;, &#39;6&#39;, &#39;7&#39;, &#39;8&#39;, &#39;9&#39;, &#39;0&#39;</span></span>
<span class="line"><span>    .byte &#39;\\n&#39;, 0x0, &#39;\\b&#39;, &#39;\\t&#39;, &#39; &#39;, &#39;-&#39;, &#39;=&#39;, &#39;[&#39;</span></span>
<span class="line"><span>    .byte &#39;]&#39;, &#39;\\\\\\&#39;, &#39;#&#39;, &#39;;&#39;, &#39;\\&#39;&#39;, &#39;\`&#39;, &#39;,&#39;, &#39;.&#39;</span></span>
<span class="line"><span>    .byte &#39;/&#39;, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0</span></span>
<span class="line"><span>    .byte 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0</span></span>
<span class="line"><span>    .byte 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0</span></span>
<span class="line"><span>    .byte 0x0, 0x0, 0x0, 0x0, &#39;/&#39;, &#39;*&#39;, &#39;-&#39;, &#39;+&#39;</span></span>
<span class="line"><span>    .byte &#39;\\n&#39;, &#39;1&#39;, &#39;2&#39;, &#39;3&#39;, &#39;4&#39;, &#39;5&#39;, &#39;6&#39;, &#39;7&#39;</span></span>
<span class="line"><span>    .byte &#39;8&#39;, &#39;9&#39;, &#39;0&#39;, &#39;.&#39;, &#39;\\\\\\&#39;, 0x0, 0x0, &#39;=&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>.align 3</span></span>
<span class="line"><span>KeysShift:</span></span>
<span class="line"><span>    .byte 0x0, 0x0, 0x0, 0x0, &#39;A&#39;, &#39;B&#39;, &#39;C&#39;, &#39;D&#39;</span></span>
<span class="line"><span>    .byte &#39;E&#39;, &#39;F&#39;, &#39;G&#39;, &#39;H&#39;, &#39;I&#39;, &#39;J&#39;, &#39;K&#39;, &#39;L&#39;</span></span>
<span class="line"><span>    .byte &#39;M&#39;, &#39;N&#39;, &#39;O&#39;, &#39;P&#39;, &#39;Q&#39;, &#39;R&#39;, &#39;S&#39;, &#39;T&#39;</span></span>
<span class="line"><span>    .byte &#39;U&#39;, &#39;V&#39;, &#39;W&#39;, &#39;X&#39;, &#39;Y&#39;, &#39;Z&#39;, &#39;!&#39;, &#39;&quot;&#39;</span></span>
<span class="line"><span>    .byte &#39;£&#39;, &#39;$&#39;, &#39;%&#39;, &#39;^&#39;, &#39;&amp;&#39;, &#39;*&#39;, &#39;(&#39;, &#39;)&#39;</span></span>
<span class="line"><span>    .byte &#39;\\n&#39;, 0x0, &#39;\\b&#39;, &#39;\\t&#39;, &#39; &#39;, &#39;_&#39;, &#39;+&#39;, &#39;{&#39;</span></span>
<span class="line"><span>    .byte &#39;}&#39;, &#39;|&#39;, &#39;~&#39;, &#39;:&#39;, &#39;@&#39;, &#39;¬&#39;, &#39;&lt;&#39;, &#39;&gt;&#39;</span></span>
<span class="line"><span>    .byte &#39;?&#39;, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0</span></span>
<span class="line"><span>    .byte 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0</span></span>
<span class="line"><span>    .byte 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0, 0x0</span></span>
<span class="line"><span>    .byte 0x0, 0x0, 0x0, 0x0, &#39;/&#39;, &#39;*&#39;, &#39;-&#39;, &#39;+&#39;</span></span>
<span class="line"><span>    .byte &#39;\\n&#39;, &#39;1&#39;, &#39;2&#39;, &#39;3&#39;, &#39;4&#39;, &#39;5&#39;, &#39;6&#39;, &#39;7&#39;</span></span>
<span class="line"><span>    .byte &#39;8&#39;, &#39;9&#39;, &#39;0&#39;, &#39;.&#39;, &#39;|&#39;, 0x0, 0x0, &#39;=&#39;</span></span></code></pre></div><p>这些表直接将前 104 个扫描码映射到 ASCII 字符作为一个字节表。我们还有一个单独的表来描述 <code>shift</code> 键对这些扫描码的影响。我使用 ASCII <code>null</code> 字符（<code>0</code>）表示所有没有直接映射的 ASCII 键（例如功能键）。退格映射到 ASCII 退格字符（8 表示 <code>\\b</code>），<code>enter</code> 映射到 ASCII 新行字符（10 表示 <code>\\n</code>）， <code>tab</code> 映射到 ASCII 水平制表符（9 表示 <code>\\t</code>）。</p><blockquote><p><code>.byte num</code> 直接插入字节常量 num 到文件。</p></blockquote><p>.</p><blockquote><p>大部分的汇编器和编译器识别转义序列；如 <code>\\t</code> 这样的字符序列会插入该特殊字符。</p></blockquote><p><code>KeyboardGetChar</code> 方法需要做以下工作：</p><ol><li>检查 <code>KeyboardAddress</code> 是否返回 <code>0</code>。如果是，则返回 0。</li><li>调用 <code>KeyboardGetKeyDown</code> 最多 6 次。每次： 1. 如果按键是 0，跳出循环。 2. 调用 <code>KeyWasDown</code>。 如果返回是，处理下一个按键。 3. 如果扫描码超过 103，进入下一个按键。 4. 调用 <code>KeyboardGetModifiers</code> 5. 如果 <code>shift</code> 是被按着的，就加载 <code>KeysShift</code> 的地址，否则加载 <code>KeysNormal</code> 的地址。 6. 从表中读出 ASCII 码值。 7. 如果是 0，进行下一个按键，否则返回 ASCII 码值并退出。</li><li>返回 0。</li></ol><p>试着自己实现。我的实现展示在下面：</p><p>1、简单的检查我们是否有键盘。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.globl KeyboardGetChar</span></span>
<span class="line"><span>KeyboardGetChar:</span></span>
<span class="line"><span>ldr r0,=KeyboardAddress</span></span>
<span class="line"><span>ldr r1,[r0]</span></span>
<span class="line"><span>teq r1,#0</span></span>
<span class="line"><span>moveq r0,#0</span></span>
<span class="line"><span>moveq pc,lr</span></span></code></pre></div><p>2、<code>r5</code> 将会保存按键的索引，<code>r4</code> 保存键盘的地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>push {r4,r5,r6,lr}</span></span>
<span class="line"><span>kbd .req r4</span></span>
<span class="line"><span>key .req r6</span></span>
<span class="line"><span>mov r4,r1</span></span>
<span class="line"><span>mov r5,#0</span></span>
<span class="line"><span>keyLoop$:</span></span>
<span class="line"><span>  mov r0,kbd</span></span>
<span class="line"><span>  mov r1,r5</span></span>
<span class="line"><span>  bl KeyboardGetKeyDown</span></span></code></pre></div><p>2.1、 如果扫描码是 0，它要么意味着有错，要么说明没有更多按键了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>teq r0,#0</span></span>
<span class="line"><span>beq keyLoopBreak$</span></span></code></pre></div><p>2.2、如果按键已经按下了，那么他就没意义了，我们只想知道按下的按键。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mov key,r0</span></span>
<span class="line"><span>bl KeyWasDown</span></span>
<span class="line"><span>teq r0,#0</span></span>
<span class="line"><span>bne keyLoopContinue$</span></span></code></pre></div><p>2.3、如果一个按键有个超过 104 的扫描码，它将会超出我们的表，所以它是无关的按键。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cmp key,#104</span></span>
<span class="line"><span>bge keyLoopContinue$</span></span></code></pre></div><p>2.4、我们需要知道修饰键来推断字符。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mov r0,kbd</span></span>
<span class="line"><span>bl KeyboardGetModifiers</span></span></code></pre></div><ol start="5"><li>当将字符更改为其 shift 变体时，我们要同时检测左 <code>shift</code> 键和右 <code>shift</code> 键。记住，<code>tst</code> 指令计算的是逻辑和，然后将其与 0 进行比较，所以当且仅当移位位都为 0 时，它才等于 0。</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tst r0,#0b00100010</span></span>
<span class="line"><span>ldreq r0,=KeysNormal</span></span>
<span class="line"><span>ldrne r0,=KeysShift</span></span></code></pre></div><p>2.6、现在我们可以从查找表加载按键了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ldrb r0,[r0,key]</span></span></code></pre></div><p>2.7、如果查找码包含一个 0，我们必须继续。为了继续，我们要增加索引，并检查是否到 6 次了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>teq r0,#0</span></span>
<span class="line"><span>bne keyboardGetCharReturn$</span></span>
<span class="line"><span>keyLoopContinue$:</span></span>
<span class="line"><span>add r5,#1</span></span>
<span class="line"><span>cmp r5,#6</span></span>
<span class="line"><span>blt keyLoop$</span></span></code></pre></div><p>3、在这里我们返回我们的按键，如果我们到达 <code>keyLoopBreak$</code> ，然后我们就知道这里没有按键被握住，所以返回 0。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>keyLoopBreak$:</span></span>
<span class="line"><span>mov r0,#0</span></span>
<span class="line"><span>keyboardGetCharReturn$:</span></span>
<span class="line"><span>pop {r4,r5,r6,pc}</span></span>
<span class="line"><span>.unreq kbd</span></span>
<span class="line"><span>.unreq key</span></span></code></pre></div><h3 id="_8、记事本操作系统" tabindex="-1">8、记事本操作系统 <a class="header-anchor" href="#_8、记事本操作系统" aria-label="Permalink to “8、记事本操作系统”">​</a></h3><p>现在我们有了 <code>KeyboardGetChar</code> 方法，可以创建一个操作系统，只打印出用户对着屏幕所写的内容。为了简单起见，我们将忽略所有非常规的键。在 <code>main.s</code>，删除 <code>bl SetGraphicsAddress</code> 之后的所有代码。调用 <code>UsbInitialise</code>，将 <code>r4</code> 和 <code>r5</code> 设置为 0，然后循环执行以下命令:</p><ol><li>调用 <code>KeyboardUpdate</code></li><li>调用 <code>KeyboardGetChar</code></li><li>如果返回 0，跳转到步骤 1</li><li>复制 <code>r4</code> 和 <code>r5</code> 到 <code>r1</code> 和 <code>r2</code> ，然后调用 <code>DrawCharacter</code></li><li>把 <code>r0</code> 加到 <code>r4</code></li><li>如果 <code>r4</code> 是 1024，将 <code>r1</code> 加到 <code>r5</code>，然后设置 <code>r4</code> 为 0。</li><li>如果 <code>r5</code> 是 768，设置 <code>r5</code> 为0</li><li>跳转到步骤 1</li></ol><p>现在编译，然后在树莓派上测试。你几乎可以立即开始在屏幕上输入文本。如果没有工作，请参阅我们的故障排除页面。</p>`,83)),t("p",null,[d[12]||(d[12]=e("当它工作时，祝贺你，你已经实现了与计算机的接口。现在你应该开始意识到，你几乎已经拥有了一个原始的操作系统。现在，你可以与计算机交互、发出命令，并在屏幕上接收反馈。在下一篇教程",-1)),a(s,{href:"https://www.cl.cam.ac.uk/projects/raspberrypi/tutorials/os/input02.html"},{default:o(()=>[...d[11]||(d[11]=[e("输入02",-1)])]),_:1}),d[13]||(d[13]=e("中，我们将研究如何生成一个全文本终端，用户在其中输入命令，然后计算机执行这些命令。",-1))]),d[36]||(d[36]=t("hr",null,null,-1)),t("p",null,[d[15]||(d[15]=e("via: ",-1)),a(s,{href:"https://www.cl.cam.ac.uk/projects/raspberrypi/tutorials/os/input01.html"},{default:o(()=>[...d[14]||(d[14]=[e("https://www.cl.cam.ac.uk/projects/raspberrypi/tutorials/os/input01.html",-1)])]),_:1})]),t("p",null,[d[20]||(d[20]=e("作者：",-1)),a(s,{href:"https://www.cl.cam.ac.uk"},{default:o(()=>[...d[16]||(d[16]=[e("Alex Chadwick",-1)])]),_:1}),d[21]||(d[21]=e(" 选题：",-1)),a(s,{href:"https://github.com/lujun9972"},{default:o(()=>[...d[17]||(d[17]=[e("lujun9972",-1)])]),_:1}),d[22]||(d[22]=e(" 译者：",-1)),a(s,{href:"https://github.com/oska874"},{default:o(()=>[...d[18]||(d[18]=[e("ezio",-1)])]),_:1}),d[23]||(d[23]=e(" 校对：",-1)),a(s,{href:"https://github.com/wxy"},{default:o(()=>[...d[19]||(d[19]=[e("wxy",-1)])]),_:1})]),t("p",null,[d[26]||(d[26]=e("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...d[24]||(d[24]=[e("LCTT",-1)])]),_:1}),d[27]||(d[27]=e(" 原创编译，",-1)),a(s,{href:"https://linux.cn/"},{default:o(()=>[...d[25]||(d[25]=[e("Linux中国",-1)])]),_:1}),d[28]||(d[28]=e(" 荣誉推出",-1))])])}const m=p(r,[["render",h]]);export{x as __pageData,m as default};
